20	describe('useFinancialAccounts', () => {
21	  beforeEach(() => {
22	    vi.clearAllMocks();
23	  });
24	
25	  const setupBaseMocks = () => {
26	    // Mock Categories
27	    const mockCategoriesQuery = {
28	      data: [
29	        { id: 1, name: 'Taxas', nature: 'debit', default_account_id: 100 },
30	      ],
31	      error: null,
32	    };
33	    const mockCatOrder = vi.fn().mockResolvedValue(mockCategoriesQuery);
34	    const mockCatEq = vi.fn().mockReturnValue({ order: mockCatOrder });
35	
36	    // Mock Cost Centers
37	    const mockCCQuery = {
38	      data: [{ id: 1, code: '001', name: 'Geral', active: true }],
39	      error: null,
40	    };
41	    const mockCCOrder = vi.fn().mockResolvedValue(mockCCQuery);
42	    const mockCCEq = vi.fn().mockReturnValue({ order: mockCCOrder });
43	
44	    // Mock Stores
45	    const mockStoresQuery = { data: [{ id: 5, nome: 'Asa Sul' }], error: null };
46	    const mockStoresOrder = vi.fn().mockResolvedValue(mockStoresQuery);
47	    const mockStoresEq = vi.fn().mockReturnValue({ order: mockStoresOrder });
48	
49	    return { mockCatEq, mockCCEq, mockStoresEq };
50	  };
51	
52	  it('deve carregar categorias, centros de custo e lojas na montagem (useEffect)', async () => {
53	    const { mockCatEq, mockCCEq, mockStoresEq } = setupBaseMocks();
54	
55	    (supabase.from as any).mockImplementation((table: string) => {
56	      if (table === 'finance_mgmt_subaccounts')
57	        return { select: vi.fn().mockReturnValue({ eq: mockCatEq }) };
58	      if (table === 'finance_cost_centers')
59	        return { select: vi.fn().mockReturnValue({ eq: mockCCEq }) };
60	      if (table === 'lojas')
61	        return { select: vi.fn().mockReturnValue({ eq: mockStoresEq }) };
62	      return {};
63	    });
64	
65	    const { result } = renderHook(() => useFinancialAccounts());
66	
67	    await waitFor(() => {
68	      expect(result.current.categories.length).toBe(1);
69	      expect(result.current.costCenters.length).toBe(1);
70	      expect(result.current.finStores.length).toBe(1);
71	      expect(result.current.categories[0].name).toBe('Taxas');
72	    });
73	  });
74	
75	  describe('fetchTransactions e CalculateSummary', () => {
76	    it('deve buscar transações com os filtros corretos e calcular o sumário', async () => {
77	      setupBaseMocks();
78	
79	      const mockTransactions = [
80	        {
81	          id: '1',
82	          valor: 1000,
83	          tipo: 'despesa',
84	          status: 'pendente',
85	          data_vencimento: '2026-02-20',
86	        }, // Overdue
87	        {
88	          id: '2',
89	          valor: 500,
90	          tipo: 'receita',
91	          status: 'pendente',
92	          data_vencimento: '2026-02-28',
93	        }, // Receivable
94	      ];
95	
96	      // Function para criar chain dinamico onde qualquer método encadeado caia nele mesmo (b),
97	      // exceto when ele usar metodos fim (then, range)
98	      const makeMockChain = (resolvedValue: any) => {
99	        const chain: any = new Proxy(
100	          {},
101	          {
102	            get: (target, prop) => {
103	              if (prop === 'then')
104	                return (cb: any) => Promise.resolve(resolvedValue).then(cb);
105	              if (prop === 'range')
106	                return vi.fn().mockResolvedValue(resolvedValue);
107	              if (prop === 'single')
108	                return vi.fn().mockResolvedValue(resolvedValue);
109	              if (prop === 'limit')
110	                return vi.fn().mockResolvedValue(resolvedValue);
111	              return vi.fn().mockReturnValue(chain);
112	            },
113	          },
114	        );
115	        return chain;
116	      };
117	
118	      const mockBaseChainStore = makeMockChain({
119	        data: mockTransactions,
120	        error: null,
121	        count: 2,
122	      });
123	      const mockSummaryChain = makeMockChain({
124	        data: mockTransactions,
125	        error: null,
126	      });
127	      const mockMonthChain = makeMockChain({ data: [] });
128	      const mockUncatChain = makeMockChain({ count: 0 });
129	
130	      (supabase.from as any).mockImplementation((table: string) => {
131	        if (table === 'contas_pagar_receber') {
132	          return {
133	            select: (fields: string, options?: any) => {
134	              if (fields === '*') return mockBaseChainStore;
135	              if (fields === 'valor, tipo, status, data_vencimento')
136	                return mockSummaryChain;
137	              if (fields === 'valor') return mockMonthChain;
138	              if (fields === 'id') return mockUncatChain;
139	              return makeMockChain({});
140	            },
141	          };
142	        }
143	
144	        // Mocks bases do useEffect
145	        return {
146	          select: vi
147	            .fn()
148	            .mockReturnValue({
149	              eq: vi
150	                .fn()
151	                .mockReturnValue({
152	                  order: vi.fn().mockResolvedValue({ data: [] }),
153	                }),
154	            }),
155	        };
156	      });
157	
158	      const { result } = renderHook(() => useFinancialAccounts());
159	
160	      const dateRange = {
161	        from: new Date('2026-02-01T12:00:00Z'),
162	        to: new Date('2026-02-28T12:00:00Z'),
163	      };
164	
165	      await act(async () => {
166	        await result.current.fetchTransactions(dateRange, 'all', '5');
167	      });
168	
169	      expect(result.current.transactions.length).toBe(2);
170	      expect(result.current.isLoading).toBe(false);
171	
172	      // Valida se o primeiro mock de Overdue mapeou t.isOverdue local
173	      expect(result.current.transactions[0].isOverdue).toBe(true);
174	
175	      // Avaliar o summary engatilhado logo depois do fetch
176	      await waitFor(() => {
177	        expect(result.current.summary.totalPayable).toBe(1000);
178	        expect(result.current.summary.totalReceivable).toBe(500);
179	      });
180	    });
181	  });
