183	  describe('Criação', () => {
184	    it('deve realizar persistência via createTransaction', async () => {
185	      setupBaseMocks();
186	      const payload = { valor: 50, tipo: 'despesa', descricao: 'Aluguel' };
187	
188	      const mockSingle = vi
189	        .fn()
190	        .mockResolvedValue({ data: { id: 'uuid-1', ...payload }, error: null });
191	      const mockSelect = vi.fn().mockReturnValue({ single: mockSingle });
192	      const mockInsert = vi.fn().mockReturnValue({ select: mockSelect });
193	
194	      (supabase.from as any).mockImplementation((table: string) => {
195	        if (table === 'contas_pagar_receber')
196	          return {
197	            insert: mockInsert,
198	            select: vi
199	              .fn()
200	              .mockReturnValue({
201	                eq: vi
202	                  .fn()
203	                  .mockReturnValue({
204	                    order: vi.fn().mockResolvedValue({ data: [] }),
205	                  }),
206	              }),
207	          };
208	        return {
209	          select: vi
210	            .fn()
211	            .mockReturnValue({
212	              eq: vi
213	                .fn()
214	                .mockReturnValue({
215	                  order: vi.fn().mockResolvedValue({ data: [] }),
216	                }),
217	            }),
218	        };
219	      });
220	
221	      const { result } = renderHook(() => useFinancialAccounts());
222	
223	      let created;
224	      await act(async () => {
225	        created = await result.current.createTransaction(payload as any);
226	      });
227	
228	      expect(mockInsert).toHaveBeenCalledWith(payload);
229	      expect(created.id).toBe('uuid-1');
230	      // A transação entra no State de forma Otimista
231	      expect(result.current.transactions[0].id).toBe('uuid-1');
232	    });
233	
234	    it('deve criar parcelas corretamente', async () => {
235	      setupBaseMocks();
236	
237	      // Mock Parent Insert
238	      const mockSingle = vi
239	        .fn()
240	        .mockResolvedValue({
241	          data: { id: 'parent-1', valor: 100 },
242	          error: null,
243	        });
244	      const mockSelect = vi.fn().mockReturnValue({ single: mockSingle });
245	      const mockInsertBase = vi.fn().mockReturnValue({ select: mockSelect });
246	
247	      // Mock Parcelas Insert
248	      const mockInsertParcelas = vi.fn().mockResolvedValue({ error: null });
249	
250	      (supabase.from as any).mockImplementation((table: string) => {
251	        if (table === 'contas_pagar_receber')
252	          return {
253	            insert: mockInsertBase,
254	            select: vi
255	              .fn()
256	              .mockReturnValue({
257	                eq: vi
258	                  .fn()
259	                  .mockReturnValue({
260	                    order: vi.fn().mockResolvedValue({ data: [] }),
261	                  }),
262	              }),
263	          };
264	        if (table === 'contas_pagar_receber_parcelas')
265	          return { insert: mockInsertParcelas };
266	        return {
267	          select: vi
268	            .fn()
269	            .mockReturnValue({
270	              eq: vi
271	                .fn()
272	                .mockReturnValue({
273	                  order: vi.fn().mockResolvedValue({ data: [] }),
274	                }),
275	            }),
276	        };
277	      });
278	
279	      const { result } = renderHook(() => useFinancialAccounts());
280	
281	      await act(async () => {
282	        // 100 reais em 3 parcelas = 33.33 x 2 e 33.34 x 1
283	        await result.current.createTransactionWithInstallments(
284	          { valor: 100, tipo: 'despesa', descricao: 'Aluguel' } as any,
285	          3,
286	          '2026-03-01',
287	        );
288	      });
289	
290	      expect(mockInsertParcelas).toHaveBeenCalledTimes(1);
291	
292	      const argsArray = mockInsertParcelas.mock.calls[0][0];
293	      expect(argsArray).toHaveLength(3);
294	      expect(argsArray[0].valor).toBeCloseTo(33.33); // 1a
295	      expect(argsArray[2].valor).toBeCloseTo(33.34); // 3a e Ultima Parcela ajuste
296	    });
297	  });
