299	  describe('Auto-accounting Generation', () => {
300	    it('deve chamar AutoAccounting silenciosamente ao marcar transacao como paga', async () => {
301	      setupBaseMocks();
302	      // Cenario: atualizando Transacao para pago
303	
304	      const mockEqUpdate = vi.fn().mockResolvedValue({ error: null });
305	      const mockUpdate = vi.fn().mockReturnValue({ eq: mockEqUpdate });
306	
307	      // Journals
308	      const mockJournalsObj = {
309	        data: [{ id: 100, type: 'bank', default_account_id: 111 }],
310	      };
311	      const mockJOrder = vi.fn().mockResolvedValue(mockJournalsObj);
312	      const mockJIn = vi.fn().mockReturnValue({ order: mockJOrder });
313	
314	      // Movies and Lines Insert mocks
315	      const mockLineInsert = vi.fn().mockResolvedValue({ error: null });
316	
317	      const mockMoveSingle = vi
318	        .fn()
319	        .mockResolvedValue({ data: { id: 999 }, error: null });
320	      const mockMoveSelect = vi
321	        .fn()
322	        .mockReturnValue({ single: mockMoveSingle });
323	      const mockMoveInsert = vi
324	        .fn()
325	        .mockReturnValue({ select: mockMoveSelect });
326	
327	      (supabase.from as any).mockImplementation((table: string) => {
328	        if (table === 'contas_pagar_receber')
329	          return {
330	            update: mockUpdate,
331	            // Inicializa a Tabela com uma Tx para o State local achar.
332	            select: vi
333	              .fn()
334	              .mockReturnValue({
335	                eq: vi
336	                  .fn()
337	                  .mockReturnValue({
338	                    order: vi
339	                      .fn()
340	                      .mockResolvedValue({
341	                        data: [
342	                          {
343	                            id: 'tx-payment',
344	                            tipo: 'despesa',
345	                            valor: 80,
346	                            descricao: 'Gasolina',
347	                          },
348	                        ],
349	                      }),
350	                  }),
351	              }),
352	          };
353	        if (table === 'account_journals')
354	          return { select: vi.fn().mockReturnValue({ in: mockJIn }) };
355	        if (table === 'account_accounts')
356	          return {
357	            select: vi
358	              .fn()
359	              .mockReturnValue({
360	                eq: vi
361	                  .fn()
362	                  .mockReturnValue({
363	                    limit: vi.fn().mockResolvedValue({ data: [{ id: 404 }] }),
364	                  }),
365	              }),
366	          }; // Fallback account id
367	        if (table === 'account_moves') return { insert: mockMoveInsert };
368	        if (table === 'account_move_lines') return { insert: mockLineInsert };
369	
370	        return {
371	          select: vi
372	            .fn()
373	            .mockReturnValue({
374	              eq: vi
375	                .fn()
376	                .mockReturnValue({
377	                  order: vi.fn().mockResolvedValue({ data: [] }),
378	                }),
379	            }),
380	        };
381	      });
382	
383	      const { result } = renderHook(() => useFinancialAccounts());
384	
385	      // Precisamos popular a transaction pro generateAccountingEntry poder extrair a Tx atual para o auto-accounting
386	      act(() => {
387	        result.current.transactions.push({
388	          id: 'tx-payment',
389	          valor: 80,
390	          tipo: 'despesa',
391	          status: 'pendente',
392	          descricao: 'Gasolina',
393	        } as any);
394	      });
395	
396	      await act(async () => {
397	        await result.current.updateStatus('tx-payment', 'pago', '2026-02-22');
398	      });
399	
400	      expect(mockUpdate).toHaveBeenCalled();
401	      expect(mockJIn).toHaveBeenCalled(); // Chamou auto-accounting
402	      expect(mockMoveInsert).toHaveBeenCalled(); // Inseriu o ledger Pai
403	      expect(mockLineInsert).toHaveBeenCalled(); // Inseriu os Débito/Crédito Lines
404	
405	      // Verifica State Local Mutado
406	      expect(
407	        result.current.transactions.find((t) => t.id === 'tx-payment')?.status,
408	      ).toBe('pago');
409	    });
410	  });
411	});
