1	/**
2	 * Hook de telemetria para campos de busca.
3	 *
4	 * Emite wide events e métricas de busca com debounce para evitar flood por keystroke.
5	 *
6	 * @example
7	 * ```ts
8	 * const { trackSearch } = useSearchTelemetry('produtos');
9	 *
10	 * useEffect(() => {
11	 *   trackSearch(searchTerm, filteredProducts.length);
12	 * }, [searchTerm, filteredProducts.length, trackSearch]);
13	 * ```
14	 */
15	
16	import { useCallback, useRef } from 'react';
17	
18	import { getTelemetryConfig } from './telemetry';
19	import { wideInfo } from './wide-events';
20	import { recordSearchQuery, recordSearchEmpty } from './metrics';
21	
22	export interface UseSearchTelemetryReturn {
23	  /** Registra uma busca. Usa debounce de 1s internamente. */
24	  trackSearch: (searchTerm: string, resultCount: number) => void;
25	}
26	
27	/**
28	 * Hook que instrumenta campos de busca por módulo.
29	 *
30	 * - Emite wide event `search.query` após debounce de 1s
31	 * - Registra métrica `momma.search.query.count` com atributo `search.module`
32	 * - Quando resultado vazio, registra também `momma.search.empty.count`
33	 * - Ignora termos com menos de 2 caracteres
34	 * - No-op quando telemetria desabilitada
35	 *
36	 * @param moduleName - Nome do módulo (ex: 'produtos', 'estoque')
37	 */
38	export function useSearchTelemetry(moduleName: string): UseSearchTelemetryReturn {
39	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
40	
41	  const trackSearch = useCallback(
42	    (searchTerm: string, resultCount: number) => {
43	      if (!getTelemetryConfig().enabled) return;
44	
45	      const trimmed = searchTerm.trim();
46	      if (trimmed.length < 2) return;
47	
48	      if (timerRef.current) clearTimeout(timerRef.current);
49	
50	      timerRef.current = setTimeout(() => {
51	        const truncatedTerm = trimmed.slice(0, 100);
52	        const hasResults = resultCount > 0;
53	
54	        wideInfo('search.query', `Busca realizada no módulo ${moduleName}`, {
55	          domain: 'search',
56	          attributes: {
57	            'search.term': truncatedTerm,
58	            'search.result_count': resultCount,
59	            'search.has_results': hasResults,
60	            'search.module': moduleName,
61	          },
62	        });
63	
64	        recordSearchQuery({ 'search.module': moduleName });
65	
66	        if (!hasResults) {
67	          recordSearchEmpty({ 'search.module': moduleName });
68	        }
69	      }, 1000);
70	    },
71	    [moduleName],
72	  );
73	
74	  return { trackSearch };
75	}
