/**
 * Executa uma função síncrona dentro de um span OpenTelemetry.
 * Se a telemetria estiver desabilitada, executa a função diretamente.
 */
export function withTraceSync<T>(
  name: string,
  fn: (span: Span | null) => T,
  attrs?: Record<string, string>,
): T {
  const tracer = getTracerSync();
  if (!tracer) return fn(null);

  return tracer.startActiveSpan(name, (span) => {
    if (attrs) {
      for (const [key, value] of Object.entries(attrs)) {
        span.setAttribute(key, value);
      }
    }
    try {
      const result = fn(span);
      span.setStatus({ code: 1 }); // OK
      return result;
    } catch (error) {
      span.setStatus({ code: 2, message: String(error) }); // ERROR
      span.recordException(error instanceof Error ? error : new Error(String(error)));
      throw error;
    } finally {
      span.end();
    }
  });
}

