// Chainable fallback that supports .range() for calculateSummary
const makeFullChain = (resolvedValue: any = { data: [], error: null }) => {
  const chain: any = new Proxy({}, {
    get: (_t, prop) => {
      if (prop === 'then') return (cb: any) => Promise.resolve(resolvedValue).then(cb);
      if (prop === 'range') return vi.fn().mockResolvedValue({ data: [], error: null });
      if (prop === 'single') return vi.fn().mockResolvedValue(resolvedValue);
      if (prop === 'limit') return vi.fn().mockResolvedValue(resolvedValue);
      return vi.fn().mockReturnValue(chain);
    },
  });
  return chain;
};

(supabase.from as any).mockImplementation((table: string) => {
  if (table === 'contas_pagar_receber')
    return {
      insert: mockInsert,
      select: vi.fn().mockReturnValue(makeFullChain()),
    };
  return { select: vi.fn().mockReturnValue(makeFullChain()) };
});

const { result } = renderHook(() => useFinancialAccounts());

let created;
await act(async () => {
  created = await result.current.createTransaction(payload as any);
